// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _test(address newCeo) internal {
        vm.assume(newCeo != address(0) && newCeo != c.ceoAddress());
        bool success = false;
        try c.DrugDealer() { success = true; } catch {}
        assertTrue(success == false || c.ceoAddress() == newCeo);
    }

    function testFuzz_test(address newCeo) public {
        _test(newCeo);
    }

    receive() external payable {}
}
